	const links = containerOrLink.querySelectorAll( 'a[href]' );
	for ( const link of links ) {
		targetLinkToNewWindow( link );
	}

	if ( containerOrLink.matches( 'a[href]' ) ) {
		targetLinkToNewWindow( containerOrLink );
	}
